with lines as (select id, host, latency_ms, status_code, attr_key, attr_value from app_logs lateral view explode(context) x as attr_key, attr_value), parsed as (select id, host, status_code, attr_key, attr_value, shiftright(status_code, 2) as status_code_high, cast((status_code & 8) != 0 as int) as has_fault from lines), with_windows as (select *, ntile(10) over (partition by host order by has_fault, id, attr_key) as has_fault_bucket, ntile(3) over (partition by attr_key order by status_code, id, attr_key) as status_code_bucket, last_value(has_fault, true) over (partition by host order by status_code, id, attr_key rows between unbounded preceding and current row) as last_known_has_fault, avg(status_code) over w_recent as status_code_avg_6 from parsed window w_recent as (partition by attr_key, host order by status_code, id, attr_key rows between 6 preceding and current row)), enriched as (select id, status_code, attr_key, status_code_high, has_fault_bucket, last_known_has_fault, lead(status_code) over (partition by host, attr_key order by last_known_has_fault, id, attr_key) as next_status_code, lag(status_code_high) over (partition by host, attr_key order by last_known_has_fault, id, attr_key) as prev_status_code_high, lead(status_code_high) over (partition by host, attr_key order by last_known_has_fault, id, attr_key) as next_status_code_high, row_number() over (partition by host, attr_key order by last_known_has_fault, id, attr_key) as event_seq from with_windows where last_known_has_fault >= 1), ranked as (select id, attr_key, last_known_has_fault, next_status_code_high from (select *, row_number() over (partition by attr_key order by next_status_code_high desc, id, attr_key) as dedup_rank from enriched) ranked where dedup_rank = 1) select id, attr_key, last_known_has_fault, case when attr_key rlike '^(region|trace)$' then 'GROUP_A' when attr_key rlike '^(version)$' then 'CORE' else 'PRIORITY' end as attr_key_zone from ranked;
